import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider {num_squares} congruent squares of side length {side_len}, all centered at the same point O. One square is axis-aligned; for k = 0, 1, ..., {num_squares_minus_1}, the k-th square is obtained by rotating the axis-aligned square by k·θ about O for some fixed acute angle θ, with 0 < θ < 90/{num_squares} degrees (so no two distinct squares share parallel sides beyond the inherent square symmetry). The intersection of all {num_squares} squares is a convex 4{num_squares}-gon whose sides lie on the sides of the various squares. Let AB denote one side of this 4{num_squares}-gon that lies on a side of one of the squares, and suppose its length equals {ab_num}/{ab_den} in lowest terms. If the area of the intersection polygon reduces to m/n in lowest terms, compute m + n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate a problem where the intersection of n congruent, evenly-rotated unit-like squares is a tangential equilateral 4n-gon.
# For squares of side length s, the inradius is s/2; with evenly spaced orientations, the 4n side directions are equally spaced,
# making the intersection polygon equilateral. Thus its perimeter is 4n * AB and its area equals r * (perimeter/2) = (s/2) * (2n * AB) = n * s * AB.
# Hence area = n * side_len * (ab_num/ab_den).

# Choose n (number of squares) at least 3 to ensure nontrivial generalization beyond the seed's 2-square idea.
n = rng.randint(3, 9)
side_len = rng.randint(1, 4)

# Choose a rational AB = p/q in lowest terms, ensure 0 < p/q < side_len (practical), and avoid trivialities.
# We'll pick q in [40, 200], p in [1, q-1], gcd(p,q)=1, and also ensure resulting area isn't an integer (to avoid trivial sums sometimes).
from math import gcd

def pick_fraction():
    for _ in range(1000):
        q = rng.randint(40, 200)
        p = rng.randint(1, q-1)
        if gcd(p, q) != 1:
            continue
        # Ensure AB < side_len (this is natural geometrically)
        if p >= side_len * q:
            continue
        # Try to avoid too-simple outcomes: avoid p == q//2 and area integer
        num_area = n * side_len * p
        den_area = q
        g = gcd(num_area, den_area)
        num_simpl = num_area // g
        den_simpl = den_area // g
        if den_simpl == 1:  # avoid integer area
            continue
        # also avoid AB very small
        if p * 5 <= q:  # ensure p/q > 0.2 approx
            continue
        return p, q
    # Fallback simple choice
    q = 99
    p = rng.choice([41, 43, 47])
    return p, q

p, q = pick_fraction()

return {
    'num_squares': n,
    'num_squares_minus_1': n-1,
    'side_len': side_len,
    'ab_num': p,
    'ab_den': q
}

    def verifier(assign):
# Validate presence
for key in ['num_squares','num_squares_minus_1','side_len','ab_num','ab_den']:
    if key not in assign:
        # Missing assignment
        return (False, None)  # missing keys
n = assign['num_squares']
nm1 = assign['num_squares_minus_1']
s = assign['side_len']
p = assign['ab_num']
q = assign['ab_den']

# Basic domain checks
if not (isinstance(n, int) and isinstance(nm1, int) and isinstance(s, int) and isinstance(p, int) and isinstance(q, int)):
    return (False, None)
if n < 3:
    # Ensure the family is genuinely beyond the 2-square case for difficulty
    return (False, None)
if nm1 != n - 1:
    return (False, None)
if s <= 0 or q <= 0 or p <= 0:
    return (False, None)
if p >= s * q:
    # AB must be less than side length of the squares
    return (False, None)

# Theoretical solution: For n evenly rotated congruent squares of side s,
# the intersection polygon is a tangential equilateral 4n-gon with incenter at O and inradius r = s/2.
# If AB is the common side length (lying on a square's side), then perimeter P = 4n * AB,
# semiperimeter = 2n * AB, and area A = r * semiperimeter = (s/2) * (2n * AB) = n * s * AB.
# Hence A = n * s * (p/q).

from math import gcd
num = n * s * p
den = q
g = gcd(num, den)
num //= g
den //= g

# Enforce non-triviality: avoid integer result (not strictly necessary but keeps difficulty)
if den == 1:
    return (False, None)

answer = num + den
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

